        String[] slice = Arrays.copyOfRange(parts, i, parts.length);
        String tryTld = join(slice);
        if (LOGGER.isDebugEnabled()) {
            LOGGER.debug(hostname + " [" + i + ".." + parts.length + "]: " + Arrays.toString(slice) + " => " + tryTld);
